CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','pharmacist','cashier')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, contact text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text UNIQUE NOT NULL, name text NOT NULL, category text NOT NULL, unit text NOT NULL DEFAULT 'unit', reorder_level integer NOT NULL DEFAULT 10 CHECK(reorder_level>=0), tax_rate numeric(5,2) NOT NULL DEFAULT 5 CHECK(tax_rate>=0 AND tax_rate<=100), supplier_id uuid REFERENCES suppliers(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), batch_number text NOT NULL, expiry_date date NOT NULL, quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), purchase_price numeric(12,2) NOT NULL CHECK(purchase_price>=0), sale_price numeric(12,2) NOT NULL CHECK(sale_price>=0), received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,batch_number));
CREATE INDEX IF NOT EXISTS batches_fefo_idx ON batches(product_id,expiry_date) WHERE quantity>0;
CREATE TABLE IF NOT EXISTS purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid REFERENCES suppliers(id), reference text UNIQUE NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id), notes text);
CREATE TABLE IF NOT EXISTS purchase_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid NOT NULL REFERENCES purchases(id), batch_id uuid NOT NULL REFERENCES batches(id), quantity integer NOT NULL CHECK(quantity>0), unit_cost numeric(12,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE IF NOT EXISTS sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text UNIQUE NOT NULL, sold_at timestamptz NOT NULL DEFAULT now(), subtotal numeric(12,2) NOT NULL, tax_total numeric(12,2) NOT NULL, total numeric(12,2) NOT NULL, status text NOT NULL DEFAULT 'completed' CHECK(status IN ('completed','partially_returned','returned')), idempotency_key text UNIQUE, created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), product_id uuid NOT NULL REFERENCES products(id), batch_id uuid NOT NULL REFERENCES batches(id), quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL, tax_rate numeric(5,2) NOT NULL, returned_quantity integer NOT NULL DEFAULT 0 CHECK(returned_quantity>=0 AND returned_quantity<=quantity));
CREATE TABLE IF NOT EXISTS stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES batches(id), product_id uuid NOT NULL REFERENCES products(id), movement_type text NOT NULL CHECK(movement_type IN ('opening','purchase','sale','return','adjustment')), quantity_delta integer NOT NULL CHECK(quantity_delta<>0), reason text NOT NULL, reference_id uuid, actor_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS movements_created_idx ON stock_movements(created_at DESC);
CREATE TABLE IF NOT EXISTS returns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), sale_item_id uuid NOT NULL REFERENCES sale_items(id), quantity integer NOT NULL CHECK(quantity>0), reason text NOT NULL, restock boolean NOT NULL DEFAULT true, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
